fn reverse(a: &[i32]) -> Vec<i32> {
    // Pre-allocate a vector of the necessary size
    let mut result = Vec::with_capacity(a.len());
    // Iterate over the slice in reverse order and push each element
    for &val in a.iter().rev() {
        result.push(val);
    }
    result
}

